'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { FileTextIcon } from '@/registry/ndeko/lib/icons';
import {
  ChatContainerContent,
  ChatContainerRoot,
  type ChatContainerContext,
} from '@/registry/ndeko/ui/chat-container';
import {
  PromptInput,
  PromptInputActions,
  PromptInputSubmit,
  PromptInputTextarea,
} from '@/registry/ndeko/ui/chat-prompt-input';
import { useTextStream } from '@/registry/ndeko/ui/chat-response-stream';
import { ScrollButton } from '@/registry/ndeko/ui/chat-scroll-button';
import { Kbd, KbdGroup } from '@/registry/ndeko/ui/kbd';

import {
  page,
  replies,
  seedTurns,
  thinkingMs,
  wordDelayMs,
  type AssistantTurn,
  type ChatTurn,
  type Feedback,
  type ReplyStatus,
} from './data';
import { rowPresenceOf } from './presence';
import { AssistantMessage, UserMessage } from './turns';

type FeedbackByTurn = Record<string, Feedback | undefined>;

function replyAt(count: number) {
  const index = count % replies.length;
  return replies[index];
}

function withReply(
  turns: ChatTurn[],
  id: string,
  status: ReplyStatus,
  text: string
) {
  return turns.map((turn) => {
    if (turn.id !== id) {
      return turn;
    }
    const updated: AssistantTurn = { ...turn, role: 'assistant', status, text };
    return updated;
  });
}

function withoutTurn(turns: ChatTurn[], id: string) {
  return turns.filter((turn) => turn.id !== id);
}

function Conversation01() {
  const [turns, setTurns] = useState<ChatTurn[]>(seedTurns);
  const [draft, setDraft] = useState('');
  const [activeId, setActiveId] = useState<string | null>(null);
  const [activeText, setActiveText] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [sentCount, setSentCount] = useState(0);
  const [feedback, setFeedback] = useState<FeedbackByTurn>({});
  const thinkingTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const chatRef = useRef<ChatContainerContext | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const isBusy = activeId !== null;

  const stream = useTextStream({
    textStream: activeText,
    mode: 'fade',
    segmentDelay: wordDelayMs,
    onComplete: finishReply,
  });

  useEffect(() => {
    return () => {
      if (thinkingTimer.current) {
        clearTimeout(thinkingTimer.current);
      }
    };
  }, []);

  function settle(id: string, status: ReplyStatus, text: string) {
    setTurns((current) => withReply(current, id, status, text));
    setActiveId(null);
    setActiveText('');
  }

  function finishReply() {
    if (!activeId) {
      return;
    }
    settle(activeId, 'done', activeText);
  }

  function startReply(id: string, text: string) {
    setIsThinking(false);
    setTurns((current) => withReply(current, id, 'streaming', ''));
    setActiveText(text);
    stream.startStreaming();
  }

  function send() {
    const text = draft.trim();
    const isEmpty = text.length === 0;
    if (isEmpty) {
      return;
    }
    if (isBusy) {
      return;
    }
    const userId = `sent-${sentCount}-user`;
    const replyId = `sent-${sentCount}-reply`;
    const reply = replyAt(sentCount);
    const userTurn: ChatTurn = { id: userId, role: 'user', text };
    const replyTurn: ChatTurn = {
      id: replyId,
      role: 'assistant',
      status: 'thinking',
      text: '',
    };
    setTurns((current) => [...current, userTurn, replyTurn]);
    setDraft('');
    setSentCount((count) => count + 1);
    setActiveId(replyId);
    setIsThinking(true);
    chatRef.current?.scrollToBottom();
    thinkingTimer.current = setTimeout(
      () => startReply(replyId, reply),
      thinkingMs
    );
  }

  function stop() {
    if (!activeId) {
      return;
    }
    if (isThinking) {
      if (thinkingTimer.current) {
        clearTimeout(thinkingTimer.current);
      }
      setIsThinking(false);
      setTurns((current) => withoutTurn(current, activeId));
      setActiveId(null);
      return;
    }
    stream.pause();
    settle(activeId, 'stopped', stream.displayedText);
  }

  function changeFeedback(id: string, choice: Feedback | undefined) {
    setFeedback((current) => ({ ...current, [id]: choice }));
  }

  return (
    <div className='bg-background text-foreground flex h-dvh min-h-[30rem] w-full flex-col'>
      <header className='flex h-14 shrink-0 items-center gap-2.5 px-4 sm:px-6'>
        <span className='gem-plate inline-flex size-7 shrink-0 items-center justify-center rounded-lg [--gem:var(--primary)] [&_svg]:size-4'>
          <FileTextIcon />
        </span>
        <div className='min-w-0'>
          <h1 className='truncate text-sm font-medium'>{page.title}</h1>
          <p className='text-muted-foreground truncate text-xs'>
            {page.space} · Ask Quillstone about this page
          </p>
        </div>
      </header>

      <ChatContainerRoot contextRef={chatRef} className='flex-1'>
        <ChatContainerContent className='mx-auto max-w-2xl px-4 pt-4 pb-2 sm:px-6'>
          <AnimatePresence initial={false}>
            {turns.map((turn) => (
              <motion.div
                key={turn.id}
                className='-mx-1 overflow-hidden px-1'
                {...rowPresence}
              >
                <div className='pb-6'>
                  {turn.role === 'user' && <UserMessage turn={turn} />}
                  {turn.role === 'assistant' && (
                    <AssistantMessage
                      turn={turn}
                      segments={stream.segments}
                      feedback={feedback[turn.id]}
                      onFeedback={(choice) => changeFeedback(turn.id, choice)}
                    />
                  )}
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </ChatContainerContent>
        <div className='pointer-events-none absolute inset-x-0 bottom-3 flex justify-center'>
          <ScrollButton wrapperClassName='pointer-events-auto' />
        </div>
      </ChatContainerRoot>

      <div className='shrink-0 px-4 pb-4 sm:px-6'>
        <div className='mx-auto w-full max-w-2xl'>
          <PromptInput
            value={draft}
            onValueChange={setDraft}
            isLoading={isBusy}
            onSubmit={send}
          >
            <PromptInputTextarea
              aria-label='Message Quillstone'
              placeholder='Ask about this page'
            />
            <PromptInputActions className='justify-between ps-2'>
              <p className='text-muted-foreground hidden items-center gap-1.5 text-xs sm:flex'>
                <KbdGroup>
                  <Kbd>Shift</Kbd>
                  <Kbd>Enter</Kbd>
                </KbdGroup>
                for a new line
              </p>
              <PromptInputSubmit onStop={stop} className='ms-auto' />
            </PromptInputActions>
          </PromptInput>
        </div>
      </div>
    </div>
  );
}

export default Conversation01;

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { FeatherIcon } from '@/registry/ndeko/lib/icons';
import { TextLoader } from '@/registry/ndeko/ui/chat-loader';
import {
  Message,
  MessageAvatar,
  MessageContent,
  MessageGlyph,
} from '@/registry/ndeko/ui/chat-message';
import {
  ResponseStreamSegments,
  type StreamSegment,
} from '@/registry/ndeko/ui/chat-response-stream';

import type { AssistantTurn, Feedback, UserTurn } from './data';
import { reader } from './data';
import { fadePresence } from './presence';
import { ReplyActions } from './reply-actions';

export function UserMessage({ turn }: { turn: UserTurn }) {
  return (
    <Message className='justify-end'>
      <MessageContent className='max-w-[85%] sm:max-w-[75%]'>
        {turn.text}
      </MessageContent>
      <MessageAvatar
        src={reader.avatar}
        alt={reader.name}
        fallback={reader.initials}
        className='hidden sm:inline-flex'
      />
    </Message>
  );
}

type AssistantMessageProps = {
  turn: AssistantTurn;
  segments: StreamSegment[];
  feedback: Feedback | undefined;
  onFeedback: (feedback: Feedback | undefined) => void;
};

export function AssistantMessage({
  turn,
  segments,
  feedback,
  onFeedback,
}: AssistantMessageProps) {
  const isThinking = turn.status === 'thinking';
  const isStreaming = turn.status === 'streaming';
  const isStopped = turn.status === 'stopped';
  const isDone = turn.status === 'done';
  const isSettled = isDone || isStopped;
  const presence = fadePresence();

  return (
    <Message>
      <MessageGlyph>
        <FeatherIcon />
      </MessageGlyph>
      <div className='min-w-0 flex-1 space-y-2 pt-1'>
        {isThinking && <TextLoader text='Thinking' />}
        {isStreaming && (
          <MessageContent variant='plain'>
            <ResponseStreamSegments segments={segments} />
          </MessageContent>
        )}
        {isSettled && (
          <MessageContent variant='plain'>{turn.text}</MessageContent>
        )}
        <AnimatePresence initial={false}>
          {isStopped && (
            <motion.p
              key='stopped'
              className='text-muted-foreground text-xs'
              {...presence}
            >
              Stopped
            </motion.p>
          )}
          {isSettled && (
            <motion.div key='actions' {...presence}>
              <ReplyActions
                text={turn.text}
                feedback={feedback}
                onFeedback={onFeedback}
              />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </Message>
  );
}

'use client';

import { CheckIcon, CopyIcon, ThumbsUpIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  MessageAction,
  MessageActions,
} from '@/registry/ndeko/ui/chat-message';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import type { CopyStatus } from './use-copied';
import { useCopied } from './use-copied';
import type { Feedback } from './data';

const COPY_TOOLTIP: Record<CopyStatus, string> = {
  idle: 'Copy',
  copied: 'Copied',
  failed: 'Couldn’t copy, select the text instead',
};

const ACTION_BUTTON =
  'text-muted-foreground aria-pressed:bg-foreground/[0.06] aria-pressed:text-foreground';

type ReplyActionsProps = {
  text: string;
  feedback: Feedback | undefined;
  onFeedback: (feedback: Feedback | undefined) => void;
};

function toggled(current: Feedback | undefined, choice: Feedback) {
  if (current === choice) {
    return undefined;
  }
  return choice;
}

export function ReplyActions({
  text,
  feedback,
  onFeedback,
}: ReplyActionsProps) {
  const { status, copy } = useCopied();
  const isCopied = status === 'copied';
  const isHelpful = feedback === 'helpful';
  const isNotHelpful = feedback === 'not-helpful';
  const tooltip = COPY_TOOLTIP[status];

  function copyReply() {
    copy(text);
  }

  function markHelpful() {
    onFeedback(toggled(feedback, 'helpful'));
  }

  function markNotHelpful() {
    onFeedback(toggled(feedback, 'not-helpful'));
  }

  return (
    <MessageActions className='-ms-1.5'>
      <MessageAction tooltip={tooltip}>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label={tooltip}
          onClick={copyReply}
          className={ACTION_BUTTON}
        >
          <Swap swapKey={String(isCopied)}>
            {isCopied && <CheckIcon className='size-3.5' />}
            {!isCopied && <CopyIcon className='size-3.5' />}
          </Swap>
        </Button>
      </MessageAction>
      <MessageAction tooltip='Helpful'>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Helpful'
          aria-pressed={isHelpful}
          onClick={markHelpful}
          className={ACTION_BUTTON}
        >
          <ThumbsUpIcon className='size-3.5' />
        </Button>
      </MessageAction>
      <MessageAction tooltip='Not helpful'>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Not helpful'
          aria-pressed={isNotHelpful}
          onClick={markNotHelpful}
          className={ACTION_BUTTON}
        >
          <ThumbsUpIcon className='size-3.5 rotate-180' />
        </Button>
      </MessageAction>
    </MessageActions>
  );
}

import type { MotionProps, Transition } from 'motion/react';

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

const ROW_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function rowPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return ROW_PRESENCE;
}

export function fadePresence() {
  return FADE_PRESENCE;
}

'use client';

import { useEffect, useRef, useState } from 'react';

export type CopyStatus = 'idle' | 'copied' | 'failed';

const RESET_AFTER_MS = 1600;

export function useCopied() {
  const [status, setStatus] = useState<CopyStatus>('idle');
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timer.current) {
        clearTimeout(timer.current);
      }
    };
  }, []);

  function showFor(nextStatus: CopyStatus) {
    if (timer.current) {
      clearTimeout(timer.current);
    }
    setStatus(nextStatus);
    timer.current = setTimeout(() => setStatus('idle'), RESET_AFTER_MS);
  }

  async function copy(text: string) {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      showFor('failed');
      return;
    }
    showFor('copied');
  }

  return { status, copy };
}

export type Person = {
  name: string;
  initials: string;
  avatar: string;
};

export type ReplyStatus = 'thinking' | 'streaming' | 'done' | 'stopped';

export type UserTurn = {
  id: string;
  role: 'user';
  text: string;
};

export type AssistantTurn = {
  id: string;
  role: 'assistant';
  text: string;
  status: ReplyStatus;
};

export type ChatTurn = UserTurn | AssistantTurn;

export type Feedback = 'helpful' | 'not-helpful';

export const reader: Person = {
  name: 'Amara Diallo',
  initials: 'AD',
  avatar: '/avatars/avatar-05.svg',
};

export const page = {
  title: 'Onboarding guide',
  space: 'People team',
};

export const seedTurns: ChatTurn[] = [
  {
    id: 'turn-1',
    role: 'user',
    text: 'The intro of the onboarding guide runs long. Can you tighten it without losing the part about buddies?',
  },
  {
    id: 'turn-2',
    role: 'assistant',
    status: 'done',
    text: 'Here is a tighter intro, down from 182 words to 74:\n\nWelcome to Fernhill. Your first two weeks are about meeting people, not shipping. Each new teammate gets a buddy who has been here at least a year. They book your first coffee and answer the questions you would rather not ask in a channel.\n\nI moved the paragraph on laptops and accounts to the Setup section, where people already look for it.',
  },
];

export const replies = [
  'A title that says what the page is for: "Your first two weeks at Fernhill". It matches how the other guides in People team are named, and it reads well in search.\n\nI can also write a one-line summary under it, so the link preview in chat says something useful.',
  'Done. The buddy paragraph is now second, since it is what most new people ask about, and the history of the office is a single sentence that links to the About page.\n\nThe intro fits on one phone screen now. The rest of the guide is unchanged.',
  'Three sections repeat the same advice about the calendar: Day one, Meetings and Tools. I would keep it in Meetings and link to it from the other two.\n\nWant me to make that change and leave a comment for Jonas, who owns the Tools section?',
];

export const thinkingMs = 700;

export const wordDelayMs = 45;
